CREATE OR REPLACE FUNCTION public.save_program_day_exercises(p_day_id uuid, p_exercises jsonb) RETURNS int LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_uid uuid := auth.uid(); v_program_id uuid; v_ex jsonb; v_name text; v_sets int; v_reps int; v_rest int; v_count int := 0; BEGIN IF v_uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF; IF p_day_id IS NULL OR p_exercises IS NULL OR jsonb_typeof(p_exercises) <> 'array' THEN RAISE EXCEPTION 'Invalid payload'; END IF; IF jsonb_array_length(p_exercises) > 100 THEN RAISE EXCEPTION 'Too many exercises'; END IF; SELECT d.program_id INTO v_program_id FROM public.program_days d WHERE d.id = p_day_id; IF v_program_id IS NULL THEN RAISE EXCEPTION 'Day not found'; END IF; IF NOT EXISTS (SELECT 1 FROM public.programs p WHERE p.id = v_program_id AND p.owner_id = v_uid) THEN RAISE EXCEPTION 'Not program owner'; END IF; FOR v_ex IN SELECT * FROM jsonb_array_elements(p_exercises) LOOP v_name := NULLIF(btrim(COALESCE(v_ex->>'name', '')), ''); IF v_name IS NULL THEN RAISE EXCEPTION 'Exercise name required'; END IF; BEGIN v_sets := COALESCE((v_ex->>'default_sets')::int, 0); v_reps := COALESCE((v_ex->>'default_reps')::int, 0); v_rest := COALESCE((v_ex->>'default_rest_seconds')::int, 90); EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'Invalid numbers for %', v_name; END; IF v_sets < 1 OR v_sets > 100 THEN RAISE EXCEPTION 'Invalid sets for %', v_name; END IF; IF v_reps < 0 OR v_reps > 5000 THEN RAISE EXCEPTION 'Invalid reps for %', v_name; END IF; IF v_rest < 0 OR v_rest > 3600 THEN RAISE EXCEPTION 'Invalid rest for %', v_name; END IF; END LOOP; DELETE FROM public.program_day_exercises WHERE program_day_id = p_day_id; FOR v_ex IN SELECT * FROM jsonb_array_elements(p_exercises) LOOP INSERT INTO public.program_day_exercises (program_day_id, name, default_sets, default_reps, default_reps_min, default_rir, default_rest_seconds, default_weight_kg, order_index) VALUES (p_day_id, btrim(v_ex->>'name'), (v_ex->>'default_sets')::int, (v_ex->>'default_reps')::int, NULLIF(v_ex->>'default_reps_min', '')::int, NULLIF(v_ex->>'default_rir', '')::int, COALESCE((v_ex->>'default_rest_seconds')::int, 90), NULLIF(v_ex->>'default_weight_kg', '')::numeric, COALESCE((v_ex->>'order_index')::int, v_count)); v_count := v_count + 1; END LOOP; UPDATE public.programs SET updated_at = now() WHERE id = v_program_id; RETURN v_count; END; $$; REVOKE ALL ON FUNCTION public.save_program_day_exercises(uuid, jsonb) FROM PUBLIC, anon; GRANT EXECUTE ON FUNCTION public.save_program_day_exercises(uuid, jsonb) TO authenticated;
